+	_, err = conn.Write([]byte{byte(pool.RpcTLS)})
+	require.NoError(t, err)
+
+	// Attempts at nested TLS connections should cause a disconnect
+	buf := []byte{0}
+	conn.SetReadDeadline(time.Now().Add(1 * time.Second))
